import{_ as i,o as a,c as t,a2 as o}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"M18-D — Benchmark del grafo 3D","description":"","frontmatter":{},"headers":[],"relativePath":"qa/graph-3d-benchmark.md","filePath":"qa/graph-3d-benchmark.md"}'),n={name:"qa/graph-3d-benchmark.md"};function s(l,e,d,r,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="m18-d-—-benchmark-del-grafo-3d" tabindex="-1">M18-D — Benchmark del grafo 3D <a class="header-anchor" href="#m18-d-—-benchmark-del-grafo-3d" aria-label="Permalink to &quot;M18-D — Benchmark del grafo 3D&quot;">​</a></h1><p>Riguarda la vista 3D del grafo (<a href="./../adr/0055-grafo-3d.html">ADR-0055</a>). Riporta ciò che è stato misurato, il metodo e i limiti. Non è il benchmark del grafo 2D, che resta in <a href="./m6-graph-benchmark.html"><code>m6-graph-benchmark.md</code></a>: l&#39;obiettivo di quello (10.000 nodi a ≥ 30 fps, M6/ADR-0013) vale per il 2D e non cambia. <strong>Il 3D non lo eredita:</strong> ha un inviluppo suo, quello qui sotto, e un tetto di 5.000 nodi.</p><p><strong>Stato:</strong> il grafo 3D è implementato e rilasciato con la 1.7.0; <code>task ci</code> completo è verde sull&#39;albero rilasciato (2026-11-15). <strong>La 1.7.1 aggiunge un livello di dettaglio intermedio, i solidi istanziati</strong>: le misure sono nella sezione <a href="#il-livello-intermedio-171">«Il livello intermedio (1.7.1)»</a>, e la tabella «Misure» qui sotto resta quella della 1.7.0, con due livelli. La revisione del codice ha corretto, con una prova e2e ciascuno, la selezione nel livello a punti (un click apriva il nodo), un nodo nascosto dal timelapse ancora cliccabile e trascinabile nel livello a sprite, la selezione riferita al grafo precedente dopo un aggiornamento, la texture dell&#39;anello di selezione non rilasciata al cambio di tema e il nuovo download del chunk dopo un errore. Ciò che non è provato resta in <em>Cosa NON è stato verificato</em>.</p><p>Nessun valore è stato stimato. Ogni riga della tabella «Misure» è <strong>una sola esecuzione</strong>, su una macchina non isolata: i numeri indicano l&#39;ordine di grandezza, non una garanzia. Le misure del livello intermedio (1.7.1) sono una o due serie per riga, su una macchina condivisa con carico variabile: stesso avvertimento.</p><h2 id="ambiente" tabindex="-1">Ambiente <a class="header-anchor" href="#ambiente" aria-label="Permalink to &quot;Ambiente&quot;">​</a></h2><p>MacBook Apple M4, macOS, Chromium headless di Playwright, finestra 1280×800. Grafo sintetico (<code>packages/workbench/src/graph/synthetic.ts</code>): <strong>tutti i nodi sono «nota»</strong>, quindi c&#39;è un solo aspetto (colore della classe più icona del tipo). Il layout gira nel Web Worker vero, in tre dimensioni; il grafo arriva dal mock dei binding (<code>window.__CLARAE_GRAPH_FIXTURE__</code>).</p><p>Due backend WebGL, scelti con <code>CLARAE_GRAPH3D_GL</code>:</p><ul><li><code>metal</code>: la GPU del Mac (<code>--use-angle=metal</code>), quello che dà una macchina con una GPU;</li><li><code>swiftshader</code>: rasterizzatore software (<code>--use-angle=swiftshader</code>), quello che dà una macchina senza GPU.</li></ul><h2 id="metodo" tabindex="-1">Metodo <a class="header-anchor" href="#metodo" aria-label="Permalink to &quot;Metodo&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLARAE_GRAPH3D_BENCH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nodi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLARAE_GRAPH3D_GL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">metal</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swiftshader</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @clarae/desktop-frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e/graph-3d-bench.spec.ts</span></span></code></pre></div><p>Il test (<code>apps/desktop/frontend/e2e/graph-3d-bench.spec.ts</code>) si salta senza <code>CLARAE_GRAPH3D_BENCH</code>, per non rallentare gli e2e normali; sul web si salta anche con la variabile (il grafo sintetico viene dal mock dei binding del desktop). Le colonne:</p><ul><li><strong>layout nel worker</strong>: tempo, nel worker, fino al raffreddamento del layout;</li><li><strong>fps durante il layout</strong>: frame disegnati diviso il tempo, mentre il layout lavora;</li><li><strong>fps in orbita</strong>: frame disegnati diviso il tempo, per 4 s di trascinamento del puntatore che ruota la camera;</li><li><strong>intervallo tra frame in orbita</strong>: mediana, 95° percentile e massimo, in ms;</li><li><strong>draw call</strong>: quante ne conta il renderer per un frame.</li></ul><p>Il livello di dettaglio dipende dai nodi (<code>graph/lod.ts</code>). <strong>Nella 1.7.0</strong> erano due: fino a 2.000 uno sprite per nodo, oltre un <code>Points</code> per aspetto; è il caso della tabella che segue. <strong>Dalla 1.7.1</strong> sono tre (sprite fino a 1.000, solidi istanziati fino a 2.000, punti oltre): vedi la sezione sul livello intermedio.</p><h2 id="misure" tabindex="-1">Misure <a class="header-anchor" href="#misure" aria-label="Permalink to &quot;Misure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>GL</th><th>nodi</th><th>link</th><th>livello</th><th>layout nel worker</th><th>fps durante il layout</th><th>fps in orbita</th><th>intervallo tra frame in orbita (mediana / p95 / max)</th><th>draw call</th></tr></thead><tbody><tr><td>Metal (GPU)</td><td>1.000</td><td>3.453</td><td>sprite</td><td>1.650 ms</td><td>59,6</td><td>60,0</td><td>16,7 / 17,5 / 18,3 ms</td><td>1.001</td></tr><tr><td>Metal</td><td>2.000</td><td>6.942</td><td>sprite</td><td>716 ms</td><td>61,1</td><td>60,0</td><td>16,7 / 17,6 / 19,6 ms</td><td>2.001</td></tr><tr><td>Metal</td><td>3.000</td><td>10.381</td><td>punti</td><td>1.077 ms</td><td>60,8</td><td>60,0</td><td>16,7 / 17,4 / 17,7 ms</td><td>2</td></tr><tr><td>Metal</td><td>5.000</td><td>17.408</td><td>punti</td><td>1.847 ms</td><td>60,6</td><td>60,0</td><td>16,7 / 17,4 / 17,8 ms</td><td>2</td></tr><tr><td>SwiftShader (software)</td><td>1.000</td><td>3.453</td><td>sprite</td><td>1.880 ms</td><td>15,0</td><td>28,1</td><td>33,7 / 42,4 / 70,8 ms</td><td>1.001</td></tr><tr><td>SwiftShader</td><td>2.000</td><td>6.942</td><td>sprite</td><td>926 ms</td><td>12,3</td><td>19,2</td><td>49,9 / 68,7 / 133,8 ms</td><td>2.001</td></tr><tr><td>SwiftShader</td><td>3.000</td><td>10.381</td><td>punti</td><td>1.292 ms</td><td>15,0</td><td>29,0</td><td>33,0 / 40,9 / 69,3 ms</td><td>2</td></tr><tr><td>SwiftShader</td><td>5.000</td><td>17.408</td><td>punti</td><td>2.086 ms</td><td>11,2</td><td>22,3</td><td>42,8 / 55,4 / 126,1 ms</td><td>2</td></tr></tbody></table><p>Lettura:</p><ul><li><strong>Con una GPU</strong> (Metal) il 3D tiene 60 fps in orbita a ogni dimensione provata, fino a 5.000 nodi, e anche mentre il layout lavora: il layout nel worker non pesa sull&#39;interfaccia.</li><li><strong>Senza GPU</strong> (software) l&#39;orbita scende a 19…29 fps e durante il layout a 11…15 fps; l&#39;intervallo massimo arriva a 134 ms. Resta usabile ma non fluido: è il caso di una macchina senza accelerazione, e la vista 2D resta disponibile.</li><li><strong>Oltre 2.000 nodi</strong> il livello a punti fa 2 draw call (una per aspetto, qui uno solo, più i link) invece di una per nodo. Con più tipi di documento ne fa una per aspetto: <strong>non è stato misurato su un vault reale</strong>.</li><li><strong>2.000 nodi si assestano prima di 1.000</strong> perché oltre 1.000 nodi il motore usa forze più leggere (<code>LARGE</code> in <code>layoutEngine3d.ts</code>: repulsione approssimata di più, a raggio limitato, raffreddamento più rapido). Non è un errore di misura.</li></ul><h2 id="il-livello-intermedio-1-7-1" tabindex="-1">Il livello intermedio (1.7.1) <a class="header-anchor" href="#il-livello-intermedio-1-7-1" aria-label="Permalink to &quot;Il livello intermedio (1.7.1)&quot;">​</a></h2><p>La 1.7.1 (M20, sessione S4) ha aggiunto tra sprite e punti un livello di <strong>solidi istanziati</strong>: un <code>InstancedMesh</code> per forma (sfera per note e presentazioni, cubo per i disegni, ottaedro per le lavagne, cilindro per le basi, cono per gli allegati, toro per i tag, icosaedro per le note non ancora create), con colore e scala per istanza; picking e trascinamento li fa la scena. Soglie in <code>graph/lod.ts</code>: <strong>sprite fino a 1.000 nodi</strong> (<code>SPRITE_NODES</code>), <strong>solidi da 1.001 a 2.000</strong> (<code>INSTANCED_NODES</code>), <strong>punti oltre</strong>. La regola era: misurare prima e dopo, e se non migliorava toglierlo e scriverlo. Migliora, quindi resta. <a href="./../adr/0055-grafo-3d.html">ADR-0055</a>, punto 7.</p><p><strong>Metodo.</strong> Lo stesso del benchmark sopra, con tre aggiunte al test <code>graph-3d-bench.spec.ts</code>:</p><ul><li><code>CLARAE_GRAPH3D_KINDS=mixed</code> costruisce un grafo di <strong>nove tipi di documento</strong> (note, presentazioni, disegni, lavagne, basi, allegati, tag, note non create), invece di sole note: è ciò che distingue i livelli, perché il livello istanziato fa una draw call per forma e non per nodo;</li><li><code>CLARAE_GRAPH3D_LOD=sprite|instanced|points</code> disegna i nodi a quel livello qualunque sia il loro numero (solo nelle build E2E), per misurare ciascun livello alla stessa dimensione;</li><li>nuove colonne: <strong>CPU di un render</strong> (mediana e p95, in ms: quanto spende la pagina per consegnare un frame) e <strong>triangoli</strong>.</li></ul><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLARAE_GRAPH3D_BENCH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nodi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLARAE_GRAPH3D_GL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">metal</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swiftshader</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  CLARAE_GRAPH3D_KINDS=mixed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CLARAE_GRAPH3D_LOD=sprite</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">instanced</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">points</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @clarae/desktop-frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e/graph-3d-bench.spec.ts</span></span></code></pre></div><p><strong>Ambiente e avvertenza.</strong> Apple M4, Chromium headless, come sopra; <strong>macchina condivisa con carico variabile</strong>; <strong>una o due serie per riga</strong>. I numeri sono ordini di grandezza, non garanzie, e non sono confrontabili con le righe della tabella «Misure» (altro grafo, altro carico).</p><p><strong>Su Metal (GPU), grafo misto.</strong></p><table tabindex="0"><thead><tr><th>Livello</th><th>Nodi</th><th>Draw call</th><th>CPU di render per frame</th><th>fps in orbita</th></tr></thead><tbody><tr><td>sprite</td><td>1.000</td><td>una per nodo (più i link)</td><td>0,9 ms</td><td>60 (limitati dal vsync)</td></tr><tr><td>sprite</td><td>2.000</td><td>una per nodo (più i link)</td><td>1,8 ms</td><td>60 (limitati dal vsync)</td></tr><tr><td>istanziato</td><td>1.000 e 2.000</td><td>8, a qualunque dimensione</td><td>0,1 ms</td><td>60 (limitati dal vsync)</td></tr></tbody></table><p>Con una GPU gli fps non distinguono i livelli (il vsync li tiene a 60): cambia il lavoro della CPU, che con i solidi è circa un nono di quello degli sprite a 1.000 nodi e circa un diciottesimo a 2.000. Le 8 draw call corrispondono alle sette forme più il <code>LineSegments</code> dei link.</p><p><strong>Su SwiftShader (rasterizzatore software), 2.000 nodi, grafo misto.</strong></p><table tabindex="0"><thead><tr><th>Livello</th><th>fps in orbita (serie con più carico / serie con meno carico)</th></tr></thead><tbody><tr><td>sprite</td><td>9,3 / 18,0</td></tr><tr><td>istanziato</td><td>11,3 / 27,3</td></tr></tbody></table><p>Senza GPU il livello istanziato è più veloce degli sprite a 2.000 nodi in entrambe le serie: in orbita da 9,3 a 11,3 fps con la macchina più carica, da 18,0 a 27,3 con meno carico.</p><p><strong>Oltre 2.000 nodi non guadagna.</strong> Rispetto ai punti il livello istanziato ha la stessa CPU di render e, su un rasterizzatore software, <strong>perde</strong>: a 5.000 nodi 7,7 fps in orbita contro 24,7 dei punti, perché disegna i triangoli dei solidi e i punti no. Per questo il livello si ferma a 2.000 nodi e oltre restano i punti.</p><p><strong>Dimensioni.</strong> Il chunk <code>Graph3D-*.js</code> cresce di 10,6 KiB e <code>layout.worker.js</code> di 0,9 kB; i budget del bundle non cambiano.</p><p><strong>Che cosa non dicono queste misure.</strong> Nulla sulla WebView reale (WKWebView, WebView2, WebKitGTK), su GPU integrate o su un vault reale; la forma dei solidi, la legenda con la forma al posto dell&#39;icona e il trascinamento di un solido non sono stati visti su una finestra vera. Il runbook <a href="./verifica-manuale-1.7.html"><code>verifica-manuale-1.7.md</code></a> dice che cosa annotare.</p><h2 id="il-punto-di-partenza-lo-spike-d0" tabindex="-1">Il punto di partenza: lo spike D0 <a class="header-anchor" href="#il-punto-di-partenza-lo-spike-d0" aria-label="Permalink to &quot;Il punto di partenza: lo spike D0&quot;">​</a></h2><p>Lo spike (un prototipo usa-e-getta, non fuso nel prodotto; le sue misure grezze sono in <a href="./graph-3d-spike-d0/"><code>docs/qa/graph-3d-spike-d0/</code></a>) ha misurato, a 3.000 nodi con i link di serie della libreria, 19 fps in orbita; con il layout della libreria sul thread principale, 5.000 nodi si assestavano in 23 s a 13,8 fps. Da lì le tre condizioni dell&#39;ADR (link in un solo <code>LineSegments</code>, layout in un worker, tetto di 5.000 nodi). Sul costo dei nodi: a 5.000 nodi su Apple M4 con Metal, 12,9 ms di CPU per frame con gli sprite e 9,3 ms con le sfere, in entrambi i casi 5.001 draw call; il livello a punti ne faceva 7 a qualunque dimensione. Per questo la 1.7.0 è uscita con due livelli di dettaglio e non con i tre del piano; la 1.7.1 ne ha aggiunto uno, perché lo spike non aveva misurato le geometrie istanziate (sezione seguente).</p><h2 id="dimensioni-build-di-produzione-minificate" tabindex="-1">Dimensioni (build di produzione, minificate) <a class="header-anchor" href="#dimensioni-build-di-produzione-minificate" aria-label="Permalink to &quot;Dimensioni (build di produzione, minificate)&quot;">​</a></h2><ul><li>Chunk lazy <code>Graph3D-*.js</code>: 791 kB sul desktop, 792 kB sul web; si scarica solo alla prima apertura del 3D. Lo spike ne aveva misurato 793 kB.</li><li><code>layout.worker.js</code>: 34,8 kB (contiene ora anche <code>d3-force-3d</code>).</li><li>Budget del bundle (ADR-0020), come stampato dalle build, nessun limite alzato: desktop <code>initial 1389 kB (limit 2000), total 19225 kB (limit 23000)</code>; web, workbench <code>initial 1950 kB (limit 2500), total 17298 kB (limit 23000)</code>; console <code>initial 697 kB (limit 700)</code> (la console non importa nulla di questo lavoro).</li></ul><h2 id="cosa-non-e-stato-verificato" tabindex="-1">Cosa NON è stato verificato <a class="header-anchor" href="#cosa-non-e-stato-verificato" aria-label="Permalink to &quot;Cosa NON è stato verificato&quot;">​</a></h2><ul><li><strong>L&#39;applicazione desktop reale.</strong> Le prove automatiche girano in Chromium (con i binding simulati e sul core WASM). La WebView del desktop è WKWebView su macOS, WebView2 su Windows, WebKitGTK su Linux: prestazioni, WebGL2 e rilascio del contesto lì non sono stati misurati. La verifica manuale con <code>task run-desktop</code> non è stata fatta e resta da fare: aprire un vault con qualche migliaio di note, passare al 3D dal pulsante della barra del grafo e dal ribbon, orbitare, trascinare un nodo, chiudere e riaprire il grafo più volte, e controllare che non compaiano avvisi sui contesti WebGL.</li><li><strong>GPU integrate, Windows e Linux.</strong> Si è misurato solo un Apple M4, con Metal e con il rasterizzatore software.</li><li><strong>Vault reali.</strong> Un grafo sintetico, di soli nodi «nota» nella tabella «Misure» e di nove tipi nel livello intermedio: la distribuzione dei gradi, il numero di tipi di documento di un vault vero (quindi le draw call del livello a punti, una per aspetto) e le etichette non sono misurati.</li><li><strong>Ripetibilità.</strong> Una sola esecuzione per riga nella tabella «Misure», una o due serie nel livello intermedio, macchina non isolata e con carico variabile, nessuna media su più prove.</li><li><strong>Hardware meno recente di un M4.</strong> Il layout (CPU, nel worker) scala con la CPU; il tetto di 5.000 nodi è una costante (<code>GRAPH3D_MAX_NODES</code> in <code>graph/settings.ts</code>) e un&#39;impostazione per vault (<code>maxNodes3d</code>, da 500 a 5.000): se serve, si abbassa il default o si alza solo dopo aver misurato.</li></ul><h2 id="prove-automatiche-collegate" tabindex="-1">Prove automatiche collegate <a class="header-anchor" href="#prove-automatiche-collegate" aria-label="Permalink to &quot;Prove automatiche collegate&quot;">​</a></h2><ul><li>vitest: <code>geometry3d.test.ts</code>, <code>layoutEngine3d.test.ts</code>, <code>GraphView.3d.test.tsx</code>, e le aggiunte a <code>graph.test.ts</code> e <code>incremental.test.ts</code>.</li><li>vitest del livello di dettaglio: <code>lod.test.ts</code> (soglie, forme, raggruppamento per forma, matrici delle istanze).</li><li>e2e sul mock dei binding e sul core WASM: <code>apps/desktop/frontend/e2e/graph-3d.spec.ts</code>, <strong>stabilizzato nella 1.7.1</strong> (timeout esplicito, 17 commutazioni invece di 20, attese più larghe sullo stato della scena, attesa della quiete della scena) (chunk lazy, scena WebGL2, legenda, pausa a riposo, click, doppio click e tastiera, nodo fissato e sbloccato, ripiego senza WebGL2, contesto rilasciato e contesto perso, livello a punti); accessibilità: <code>a11y.spec.ts</code> (voce «graph view in 3D»).</li><li>sicurezza: <code>web/e2e-security/workbench-csp.spec.ts</code> (handler e CSP di produzione: nessuna violazione, nessuna richiesta fuori origine; il test del 3D stava in <code>graph3d-csp.spec.ts</code> fino alla 1.7.0 e dalla 1.7.1 sta in questo file, dove prova anche il livello istanziato).</li><li>Go: <code>TestBuildDocuments</code> in <code>apps/desktop/internal/graph/graph_test.go</code> (disegni, lavagne e basi come nodi).</li></ul>`,40)])])}const g=i(n,[["render",s]]);export{u as __pageData,g as default};
